4 & $30.0-34.9 \text{ Kg/m}^2$ & স্থলতার ১ম স্তর \\
\hline
5 & $35.0-39.9 \text{ Kg/m}^2$ & স্থলতার ২য় স্তর \\
\hline
6 & $\geq 40.0 \text{ Kg/m}^2$ & স্থলতার ৩য় স্তর \\
\hline
\end{tabular}

